public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    for (String str : strings) {
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i < str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                substrings.add(str.substring(i, j));
            }
        }

        Set<String> reversedSubstrings = new HashSet<>();
        for (String sub : substrings) {
            reversedSubstrings.add(new StringBuilder(sub).reverse().toString());
        }

        for (String revers : reversedSubstrings) {
            for (String s : strings) {
                if (s.contains(revers) || s.contains(reversed(revers))) {
                    int length = Math.max(sub.length(), reversedSub.length());
                    if (length > maxLength) {
                        maxLength = length;
                    }
                }
            }
        }
    }

    return maxLength;
}

