public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph to represent the intersections and their connections
    Graph<Integer, Integer> graph = new DefaultGraph<>();

    // Add intersections to the graph
    for (int i = 0; i < n; i++) {
        graph.addVertex(i);
    }

    // Add paths to the graph
    for (int[] path : paths) {
        graph.addEdge(path[0], path[1]);
        graph.addEdge(path[1], path[0]);
    }

    // Check if there is a path from the start intersection to the end intersection
    boolean hasPath = Graphs.hasPath(graph, start[0], end[0]);

    // Return the result
    if (hasPath) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

