public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list to represent the graph
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    // Build the graph based on the given paths
    for (int[] path : paths) {
        graph.get(path[0]).add(path[1]);
        graph.get(path[1]).add(path[0]);
    }

    // Create a visited array to keep track of visited vertices
    boolean[] visited = new boolean[n];

    // Helper method to perform DFS
    boolean dfs(int current, int end, boolean[] visited, List<List<Integer>> graph) {
        if (current == end) {
            return true;
        }
        visited[current] = true;
        for (int neighbor : graph.get(current)) {
            if (!visited[neighbor] && dfs(neighbor, end, visited, graph)) {
                return true;
            }
        }
        visited[current] = false;
        return false;
    }

    // Perform DFS from the start intersection
    if (dfs(start[0], end[0], visited, graph)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

