public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    Set<Character> set2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        set1.add(Character.toLowerCase(c));
    }

    for (char c : word2.toCharArray()) {
        set2.add(Character.toLowerCase(c));
    }

    int commonCount = 0;
    for (char c : set1) {
        if (set2.contains(c)) {
            commonCount++;
        }
    }

    int lengthSum = word1.length() + word2.length();

    int gcd = gcd(commonCount, lengthSum);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (lengthSum / gcd);
}

