    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLen = 0;

    // Create 4 arrays to store the length of continuous 1s in each direction
    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Horizontal line
                if (j > 0) {
                    horizontal[i][j] = horizontal[i][j - 1] + 1;
                } else {
                    horizontal[i][j] = 1;
                }
                maxLen = Math.max(maxLen, horizontal[i][j]);

                // Vertical line
                if (i > 0) {
                    vertical[i][j] = vertical[i - 1][j] + 1;
                } else {
                    vertical[i][j] = 1;
                }
                maxLen = Math.max(maxLen, vertical[i][j]);

                // Diagonal line
                if (i > 0 && j > 0) {
                    diagonal[i][j] = diagonal[i - 1][j - 1] + 1;
                } else {
                    diagonal[i][j] = 1;
                }
                maxLen = Math.max(maxLen, diagonal[i][j]);

                // Anti-diagonal line
                if (i > 0 && j < cols - 1) {
                    antiDiagonal[i][j] = antiDiagonal[i - 1][j + 1] + 1;
                } else {
                    antiDiagonal[i][j] = 1;
                }
                maxLen = Math.max(maxLen, antiDiagonal[i][j]);
            }
        }
    }

    return maxLen;
}

