public static int squarePermutations(int[] A) {
    int N = A.length;
    int[] dp = new int[1 << N];
    dp[0] = 1;

    for (int i = 0; i < 1 << N; i++) {
        int j = 0;
        while ((i & (1 << j)) == 0) {
            j++;
        }
        int k = j + 1;
        while (k < N) {
            if ((i & (1 << k)) == 0) {
                int sum = A[j] + A[k];
                int root = (int) Math.sqrt(sum);
                if (root * root == sum) {
                    dp[i | (1 << k)] += dp[i];
                }
            }
            k++;
        }
    }

    return dp[(1 << N) - 1];
}

