public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, i = 0;

    while (i < result.length) {
        result[i++] = mat[r][c];
        if ((r + c) % 2 == 0) { // Going up
            if (c == cols - 1) r++;
            else if (r == 0) c++;
            else r--;
        } else { // Going down
            if (r == rows - 1) c++;
            else if (c == 0) r++;
            else c--;
        }
    }

    return result;
}

