public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();

    // Find the first digit that can be swapped to get a larger number
    int i;
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to rearrange to get a larger number)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
    int j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i-th digit) in ascending order
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the char array back to an integer
    return Integer.parseInt(new String(digits));
}

