public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Fill the array with a large value (infinity)
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    // Base case: 0 has 0 perfect squares
    dp[0] = 0;

    // Calculate the minimum number of perfect squares for each number from 1 to n
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // The result is the minimum number of perfect squares for the target number n
    return dp[n];
}

